-- LiTo 0.6.63 compact resources. Select the intended LiTo database first.
-- Fresh install only: no DROP, no REPLACE; existing tables cause an error.
SET NAMES utf8;
CREATE TABLE `lito_resource_buff` (
  `skill_id` smallint(5) unsigned NOT NULL,
  `icon_id` smallint(5) unsigned NOT NULL,
  `skill_panel_icon` smallint(5) unsigned DEFAULT NULL,
  `status_slot` smallint(5) unsigned NOT NULL,
  `packet_opcode` tinyint(3) unsigned NOT NULL,
  `packet_selector` smallint(5) unsigned NOT NULL,
  `server_duration_seconds` int(10) unsigned NOT NULL,
  `resource_duration_seconds` int(10) unsigned DEFAULT NULL,
  `off_icon_id` smallint(5) unsigned DEFAULT NULL,
  `clear_duration_seconds` int(10) unsigned NOT NULL,
  `mapping_kind` varchar(191) NOT NULL,
  `verification` text NOT NULL,
  `resource_version` varchar(191) NOT NULL,
  `asset` longtext,
  `resource_named_icon` smallint(5) unsigned DEFAULT NULL,
  `semantic_conflict` tinyint(4) DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`skill_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_map` (
  `map_id` smallint(5) unsigned NOT NULL,
  `raw_slot` smallint(5) unsigned NOT NULL,
  `category` varchar(32) NOT NULL,
  `name` varchar(96) NOT NULL,
  `resource_version` varchar(96) NOT NULL,
  `resource_exists` tinyint(4) NOT NULL,
  `rule_in_20261013_snapshot` tinyint(4) NOT NULL,
  `gameplay_confirmed` tinyint(4) DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`map_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_map_page` (
  `wire_page` tinyint(3) unsigned NOT NULL,
  `zero_based_index` tinyint(3) unsigned NOT NULL,
  `image_resource_id` smallint(5) unsigned NOT NULL,
  `display_map_id` smallint(5) unsigned NOT NULL,
  `asset` longtext NOT NULL,
  `pe_source_id` int(10) unsigned NOT NULL,
  `table_virtual_address` varchar(32) NOT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`wire_page`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_npc_identity` (
  `resource_index` smallint(5) unsigned NOT NULL,
  `wire_name_id` smallint(5) unsigned NOT NULL,
  `description` varchar(191) NOT NULL,
  `actor_gfx` smallint(6) DEFAULT NULL,
  `x` smallint(6) DEFAULT NULL,
  `y` smallint(6) DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`resource_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_pending` (
  `id` int(11) NOT NULL,
  `category` varchar(32) NOT NULL,
  `source_table` varchar(96) NOT NULL,
  `record_key` varchar(96) DEFAULT NULL,
  `evidence_status` varchar(40) NOT NULL,
  `evidence_note` text NOT NULL,
  `known_evidence` text NOT NULL,
  `missing_evidence` text NOT NULL,
  `required_evidence` text NOT NULL,
  `archive_ref` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='LiTo 統一待補證據與封存資料備註';
CREATE TABLE `lito_resource_portal` (
  `source_map_id` smallint(5) unsigned NOT NULL,
  `source_x` smallint(5) unsigned NOT NULL,
  `source_y` smallint(5) unsigned NOT NULL,
  `target_map_id` smallint(5) unsigned NOT NULL,
  `target_x` smallint(5) unsigned NOT NULL,
  `target_y` smallint(5) unsigned NOT NULL,
  `raw_tag` smallint(6) DEFAULT NULL,
  `resource_version` varchar(96) NOT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`source_map_id`,`source_x`,`source_y`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_projectile` (
  `projectile_key` varchar(96) NOT NULL,
  `skill_id` smallint(5) unsigned DEFAULT NULL,
  `projectile_gfx` smallint(5) unsigned NOT NULL,
  `packet_opcode` tinyint(3) unsigned NOT NULL,
  `flight_type` tinyint(3) unsigned NOT NULL,
  `resource_version` varchar(96) NOT NULL,
  `impact_gfx` smallint(5) unsigned DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`projectile_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_release` (
  `release_id` int(11) NOT NULL,
  `source_version` varchar(32) NOT NULL,
  `qualified_version` varchar(32) NOT NULL,
  `package_hash` char(64) NOT NULL,
  `note` text NOT NULL,
  PRIMARY KEY (`release_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_skill_value` (
  `record_type` varchar(64) NOT NULL,
  `skill_id` smallint(5) unsigned NOT NULL,
  `field_name` varchar(64) NOT NULL,
  `value` int(11) NOT NULL,
  `binding` varchar(96) NOT NULL,
  `enabled` tinyint(4) NOT NULL,
  `evidence_status` varchar(32) NOT NULL,
  `evidence_note` text NOT NULL,
  PRIMARY KEY (`record_type`,`skill_id`,`field_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `lito_resource_zone` (
  `zone_key` varchar(32) NOT NULL,
  `color_index` smallint(6) NOT NULL,
  `map_id` smallint(5) unsigned NOT NULL,
  `min_x` smallint(5) unsigned NOT NULL,
  `min_y` smallint(5) unsigned NOT NULL,
  `max_x` smallint(5) unsigned NOT NULL,
  `max_y` smallint(5) unsigned NOT NULL,
  `red` tinyint(3) unsigned NOT NULL,
  `green` tinyint(3) unsigned NOT NULL,
  `blue` tinyint(3) unsigned NOT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT '0',
  `evidence_status` varchar(32) NOT NULL DEFAULT 'reference',
  `evidence_note` text,
  PRIMARY KEY (`zone_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
